const cfg = $('⚙️ Configurações').first().json;

const agora = new Date();
const dow = agora.getDay();
const recuo = (dow === 0 ? 6 : dow - 1) + 7;

const seg = new Date(agora);
seg.setDate(agora.getDate() - recuo);
const dom = new Date(seg);
dom.setDate(seg.getDate() + 6);

const fmtPG = (d) => d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
const fmtLabel = (d) => String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0') + '/' + d.getFullYear();

return [{
  json: {
    start_date: fmtPG(seg),
    end_date: fmtPG(dom),
    dataRef: fmtLabel(seg) + ' a ' + fmtLabel(dom),
    modo_producao: cfg.modo_producao,
    email_teste: cfg.email_teste
  }
}];

const items = $input.all();
const cfg = $('⚙️ Configurações').first().json;
const per = $('Calcular Período').first().json;
const dataRef = per.dataRef;
const modoProducao = cfg.modo_producao;
const emailTeste = cfg.email_teste;

// — Formatadores —
const fmtMoeda = (v) => {
  if (!v && v !== 0) return 'R$ 0,00';
  return 'R$ ' + parseFloat(v).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
};
const fmtLitros = (v) => {
  if (!v && v !== 0) return '0,00';
  return parseFloat(v).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
};
const fmtKm = (v) => {
  if (!v && v !== 0) return '0';
  return Math.round(parseFloat(v)).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
};
const fmtDec = (v, dec = 2) => {
  if (v === null || v === undefined || isNaN(parseFloat(v))) return '—';
  return parseFloat(v).toFixed(dec).replace('.', ',');
};

// — Totais gerais —
let sumKm = 0, sumLitrosGas = 0, sumValorGas = 0;
let sumLitrosDie = 0, sumValorDie = 0;
let sumLitrosAlc = 0, sumValorAlc = 0;
let sumLitros = 0, sumValor = 0, sumVeiculos = 0;

const filiais = [];
for (const item of items) {
  const f = item.json;
  const km       = parseFloat(f.total_km)       || 0;
  const lGas     = parseFloat(f.litros_gasolina) || 0;
  const vGas     = parseFloat(f.valor_gasolina)  || 0;
  const lDie     = parseFloat(f.litros_diesel)   || 0;
  const vDie     = parseFloat(f.valor_diesel)    || 0;
  const lAlc     = parseFloat(f.litros_alcool)   || 0;
  const vAlc     = parseFloat(f.valor_alcool)    || 0;
  const lTot     = parseFloat(f.total_litros)    || 0;
  const vTot     = parseFloat(f.total_valor)     || 0;
  const veic     = parseInt(f.qtd_veiculos)      || 0;
  const custoKm  = f.custo_por_km;
  const kmL      = f.km_por_litro;

  sumKm        += km;
  sumLitrosGas += lGas;  sumValorGas += vGas;
  sumLitrosDie += lDie;  sumValorDie += vDie;
  sumLitrosAlc += lAlc;  sumValorAlc += vAlc;
  sumLitros    += lTot;  sumValor    += vTot;
  sumVeiculos  += veic;

  filiais.push({
    nome: f.filial_nome, km, lGas, vGas, lDie, vDie,
    lAlc, vAlc, lTot, vTot, veic, custoKm, kmL
  });
}

const custoKmGeral = sumKm > 0 ? (sumValor / sumKm) : null;
const kmLGeral     = sumLitros > 0 && sumKm > 0 ? (sumKm / sumLitros) : null;

// — Monta as linhas da tabela HTML —
let rowsHtml = '';
for (const f of filiais) {
  // Cor do custo/km: acima da média = vermelho, abaixo = verde
  let corCustoKm = '#2D3436';
  if (f.custoKm !== null && custoKmGeral !== null) {
    const desvio = ((f.custoKm - custoKmGeral) / custoKmGeral) * 100;
    if (desvio > 5) corCustoKm = '#B02A30';
    else if (desvio < -5) corCustoKm = '#4B7F52';
  }

  rowsHtml += `<tr>
    <td style="padding:10px 12px;border-bottom:1px solid #F0EFEC;font-size:13px;font-weight:600;color:#2D3436">${f.nome}</td>
    <td style="padding:10px 8px;border-bottom:1px solid #F0EFEC;font-size:13px;text-align:center;color:#6B7280">${f.veic}</td>
    <td style="padding:10px 8px;border-bottom:1px solid #F0EFEC;font-size:13px;text-align:right;color:#2D3436">${fmtKm(f.km)}</td>
    <td style="padding:10px 8px;border-bottom:1px solid #F0EFEC;font-size:12px;text-align:right;color:#6B7280">${fmtLitros(f.lGas)}</td>
    <td style="padding:10px 8px;border-bottom:1px solid #F0EFEC;font-size:12px;text-align:right;color:#2D3436">${fmtMoeda(f.vGas)}</td>
    <td style="padding:10px 8px;border-bottom:1px solid #F0EFEC;font-size:12px;text-align:right;color:#6B7280">${fmtLitros(f.lDie)}</td>
    <td style="padding:10px 8px;border-bottom:1px solid #F0EFEC;font-size:12px;text-align:right;color:#2D3436">${fmtMoeda(f.vDie)}</td>
    <td style="padding:10px 8px;border-bottom:1px solid #F0EFEC;font-size:13px;text-align:right;font-weight:600;color:#2D3436">${fmtLitros(f.lTot)}</td>
    <td style="padding:10px 8px;border-bottom:1px solid #F0EFEC;font-size:13px;text-align:right;font-weight:700;color:#2D3436">${fmtMoeda(f.vTot)}</td>
    <td style="padding:10px 8px;border-bottom:1px solid #F0EFEC;font-size:13px;text-align:right;font-weight:700;color:${corCustoKm}">${f.custoKm !== null ? 'R$ ' + fmtDec(f.custoKm, 2) : '—'}</td>
  </tr>`;
}

// — Linha TOTAL GERAL —
const totalRow = `<tr style="background:#F1F5F9">
  <td style="padding:11px 12px;font-size:13px;font-weight:700;color:#0F172A;border-top:2px solid #CBD5E1">TOTAL GERAL</td>
  <td style="padding:11px 8px;font-size:13px;text-align:center;font-weight:700;color:#0F172A;border-top:2px solid #CBD5E1">${sumVeiculos}</td>
  <td style="padding:11px 8px;font-size:13px;text-align:right;font-weight:700;color:#0F172A;border-top:2px solid #CBD5E1">${fmtKm(sumKm)}</td>
  <td style="padding:11px 8px;font-size:12px;text-align:right;font-weight:700;color:#0F172A;border-top:2px solid #CBD5E1">${fmtLitros(sumLitrosGas)}</td>
  <td style="padding:11px 8px;font-size:12px;text-align:right;font-weight:700;color:#0F172A;border-top:2px solid #CBD5E1">${fmtMoeda(sumValorGas)}</td>
  <td style="padding:11px 8px;font-size:12px;text-align:right;font-weight:700;color:#0F172A;border-top:2px solid #CBD5E1">${fmtLitros(sumLitrosDie)}</td>
  <td style="padding:11px 8px;font-size:12px;text-align:right;font-weight:700;color:#0F172A;border-top:2px solid #CBD5E1">${fmtMoeda(sumValorDie)}</td>
  <td style="padding:11px 8px;font-size:13px;text-align:right;font-weight:700;color:#0F172A;border-top:2px solid #CBD5E1">${fmtLitros(sumLitros)}</td>
  <td style="padding:11px 8px;font-size:13px;text-align:right;font-weight:700;color:#0F172A;border-top:2px solid #CBD5E1">${fmtMoeda(sumValor)}</td>
  <td style="padding:11px 8px;font-size:13px;text-align:right;font-weight:700;color:#0F172A;border-top:2px solid #CBD5E1">${custoKmGeral !== null ? 'R$ ' + fmtDec(custoKmGeral, 2) : '—'}</td>
</tr>`;

const faixaTeste = modoProducao ? '' : '<tr><td style="background:#C85F15;padding:7px 40px;text-align:center;font-size:11px;color:#fff;font-weight:600;letter-spacing:0.05em;text-transform:uppercase">⚠️ MODO TESTE · Destinatários reais omitidos</td></tr>';

const emailFinal = modoProducao
  ? 'torredecontrole@gritsch.com.br,diretoria@gritsch.com.br,sandro@gritsch.com.br,flavio@gritsch.com.br,fabio.pepplow@gritsch.com.br'
  : emailTeste;

// — HTML do E-mail —
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head>
<body style="margin:0;padding:0;background:#F5F4F1;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Arial,sans-serif">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#F5F4F1;padding:32px 0"><tr><td align="center">
<table width="900" cellpadding="0" cellspacing="0" style="background:#fff;border:1px solid #E8E6E0">

${faixaTeste}

<!-- HEADER -->
<tr><td style="padding:32px 40px 20px;border-bottom:1px solid #E8E6E0">
<table width="100%"><tr>
<td style="vertical-align:middle"><img src="https://gritsch.com.br/grupogritsch.jpg" width="80" style="display:block" alt="Gritsch"></td>
<td style="text-align:right;vertical-align:middle">
<div style="font-size:10px;letter-spacing:0.15em;text-transform:uppercase;color:#6B7280;font-weight:500">Torre de Controle</div>
<div style="font-size:11px;color:#9CA3AF;margin-top:2px">Relatório Semanal de Combustível</div>
</td></tr></table></td></tr>

<!-- TÍTULO -->
<tr><td style="padding:24px 40px 8px">
<div style="font-size:22px;color:#2D3436;font-weight:600">📊 Relatório Semanal — Combustível por Filial</div>
<div style="font-size:13px;color:#6B7280;margin-top:4px">Período: ${dataRef}</div>
</td></tr>

<!-- 4 KPI CARDS -->
<tr><td style="padding:12px 40px 20px">
<table width="100%" cellpadding="0" cellspacing="0"><tr>
<td width="25%" style="padding-right:10px;border-right:1px solid #F0EFEC;vertical-align:top">
<div style="font-size:10px;letter-spacing:0.08em;text-transform:uppercase;color:#9CA3AF;font-weight:600">KM Total Rodado</div>
<div style="font-size:20px;color:#2D3436;font-weight:600;margin-top:4px">${fmtKm(sumKm)} km</div>
</td>
<td width="25%" style="padding:0 10px;border-right:1px solid #F0EFEC;vertical-align:top">
<div style="font-size:10px;letter-spacing:0.08em;text-transform:uppercase;color:#9CA3AF;font-weight:600">Litros Totais</div>
<div style="font-size:20px;color:#2D3436;font-weight:600;margin-top:4px">${fmtLitros(sumLitros)} L</div>
</td>
<td width="25%" style="padding:0 10px;border-right:1px solid #F0EFEC;vertical-align:top">
<div style="font-size:10px;letter-spacing:0.08em;text-transform:uppercase;color:#9CA3AF;font-weight:600">Valor Total Gasto</div>
<div style="font-size:20px;color:#1E5799;font-weight:600;margin-top:4px">${fmtMoeda(sumValor)}</div>
</td>
<td width="25%" style="padding-left:10px;vertical-align:top">
<div style="font-size:10px;letter-spacing:0.08em;text-transform:uppercase;color:#4B7F52;font-weight:600">Custo / KM Médio</div>
<div style="font-size:20px;color:#4B7F52;font-weight:600;margin-top:4px">${custoKmGeral !== null ? 'R$ ' + fmtDec(custoKmGeral, 2) + ' /km' : '—'}</div>
</td>
</tr></table>
</td></tr>

<!-- TABELA POR FILIAL -->
<tr><td style="padding:0 40px 8px">
<div style="font-size:11px;letter-spacing:0.12em;text-transform:uppercase;color:#6B7280;font-weight:600;margin-bottom:10px;border-left:3px solid #1E5799;padding-left:8px">Detalhamento por Filial</div>
<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse">
<tr style="background:#F8FAFC">
<th style="padding:10px 12px;text-align:left;font-size:10px;text-transform:uppercase;color:#64748B;font-weight:600;border-bottom:2px solid #CBD5E1">Filial</th>
<th style="padding:10px 8px;text-align:center;font-size:10px;text-transform:uppercase;color:#64748B;font-weight:600;border-bottom:2px solid #CBD5E1">Veíc.</th>
<th style="padding:10px 8px;text-align:right;font-size:10px;text-transform:uppercase;color:#64748B;font-weight:600;border-bottom:2px solid #CBD5E1">KM Rod.</th>
<th style="padding:10px 8px;text-align:right;font-size:10px;text-transform:uppercase;color:#64748B;font-weight:600;border-bottom:2px solid #CBD5E1;background:#FFFBEB">Gas (L)</th>
<th style="padding:10px 8px;text-align:right;font-size:10px;text-transform:uppercase;color:#64748B;font-weight:600;border-bottom:2px solid #CBD5E1;background:#FFFBEB">Gas (R$)</th>
<th style="padding:10px 8px;text-align:right;font-size:10px;text-transform:uppercase;color:#64748B;font-weight:600;border-bottom:2px solid #CBD5E1;background:#F0F9FF">Diesel (L)</th>
<th style="padding:10px 8px;text-align:right;font-size:10px;text-transform:uppercase;color:#64748B;font-weight:600;border-bottom:2px solid #CBD5E1;background:#F0F9FF">Diesel (R$)</th>
<th style="padding:10px 8px;text-align:right;font-size:10px;text-transform:uppercase;color:#64748B;font-weight:600;border-bottom:2px solid #CBD5E1">Total (L)</th>
<th style="padding:10px 8px;text-align:right;font-size:10px;text-transform:uppercase;color:#64748B;font-weight:600;border-bottom:2px solid #CBD5E1">Total (R$)</th>
<th style="padding:10px 8px;text-align:right;font-size:10px;text-transform:uppercase;color:#64748B;font-weight:600;border-bottom:2px solid #CBD5E1;background:#F0FDF4">Custo/KM</th>
</tr>
${rowsHtml}
${totalRow}
</table>
</td></tr>

<!-- LEGENDA -->
<tr><td style="padding:16px 40px 12px">
<div style="font-size:11px;color:#9CA3AF;font-style:italic;line-height:1.6">
📌 <strong>Custo/KM</strong> = Valor Total Gasto ÷ KM Rodado · <span style="color:#B02A30">■</span> acima de +5% da média · <span style="color:#4B7F52">■</span> abaixo de -5% da média<br>
📌 KM Rodado calculado por MAX(hodômetro) − MIN(hodômetro) da semana, por veículo. Filiais sem leitura válida de hodômetro aparecem com \"—\".\n</div>
</td></tr>

<!-- FOOTER -->
<tr><td style="padding:24px 40px;border-top:1px solid #E8E6E0;background:#FAFAF8">
<div style="font-size:11px;color:#9CA3AF;line-height:1.7">
Relatório gerado automaticamente pela Torre de Controle.<br>
Fonte: DW TruckPag · Dúvidas: torredecontrole@gritsch.com.br
</div>
</td></tr>

</table>
<div style="margin-top:14px;font-size:10px;color:#9CA3AF;letter-spacing:0.08em">GRITSCH TRANSPORTES · SOLUÇÕES EM LOGÍSTICA</div>
</td></tr></table></body></html>`;

// — CSV para anexo —
const esc = (val) => {
  if (val === null || val === undefined) return '';
  return '"' + String(val).replace(/"/g, '""') + '"';
};

let csv = 'Filial;Veiculos;KM Rodado;Litros Gasolina;Valor Gasolina (R$);Litros Diesel;Valor Diesel (R$);Litros Alcool;Valor Alcool (R$);Total Litros;Total Valor (R$);Custo por KM (R$);KM por Litro\n';
for (const f of filiais) {
  csv += `${esc(f.nome)};${f.veic};${f.km};${parseFloat(f.lGas).toFixed(2).replace('.',',')};${parseFloat(f.vGas).toFixed(2).replace('.',',')};${parseFloat(f.lDie).toFixed(2).replace('.',',')};${parseFloat(f.vDie).toFixed(2).replace('.',',')};${parseFloat(f.lAlc).toFixed(2).replace('.',',')};${parseFloat(f.vAlc).toFixed(2).replace('.',',')};${parseFloat(f.lTot).toFixed(2).replace('.',',')};${parseFloat(f.vTot).toFixed(2).replace('.',',')};${f.custoKm !== null ? parseFloat(f.custoKm).toFixed(2).replace('.',',') : ''};${f.kmL !== null ? parseFloat(f.kmL).toFixed(2).replace('.',',') : ''}\n`;
}
// Linha total
csv += `"TOTAL GERAL";${sumVeiculos};${sumKm};${sumLitrosGas.toFixed(2).replace('.',',')};${sumValorGas.toFixed(2).replace('.',',')};${sumLitrosDie.toFixed(2).replace('.',',')};${sumValorDie.toFixed(2).replace('.',',')};${sumLitrosAlc.toFixed(2).replace('.',',')};${sumValorAlc.toFixed(2).replace('.',',')};${sumLitros.toFixed(2).replace('.',',')};${sumValor.toFixed(2).replace('.',',')};${custoKmGeral !== null ? custoKmGeral.toFixed(2).replace('.',',') : ''};${kmLGeral !== null ? kmLGeral.toFixed(2).replace('.',',') : ''}\n`;

const dateSuf = dataRef.replace(/\//g, '-').replace(/ /g, '');
return [{
  json: { htmlEmail: html, emailFinal },
  binary: {
    attachment_relatorio: {
      data: Buffer.from('\ufeff' + csv, 'utf-8').toString('base64'),
      mimeType: 'text/csv',
      fileName: `Relatorio_Combustivel_Filiais_${dateSuf}.csv`
    }
  }
}];
